async function main(ctx) {
  const resp = ctx.lastOutputOf('list_templates') || {};
  const body = resp.body;

  // Expected Starships envelope: { success: true, data: { connectors: [...] } }
  const connectors = body?.success === true
    ? (body?.data?.connectors || body?.data?.items || body?.data || [])
    : [];

  const arr = Array.isArray(connectors) ? connectors : [];

  return {
    count: arr.length,
    connectors: arr.map((c) => ({
      id: c?.id,
      slug: c?.slug,
      provider: c?.provider,
      name: c?.name,
      description: c?.description,
      authType: c?.auth?.type,
      isEnabled: c?.isEnabled,
      version: c?.version,
      category: c?.category,
      updatedAt: c?.updatedAt
    }))
  };
}
